  }, [handleUpdateCategoryName, mode]);

  const isSearching = searchTerm.trim() !== '';
  const isSpecialFilterActive = advancedMode && (showOnlyUrgent || showOnlyDefaultCompleted);

  const categoriesForList = useMemo(() => {
    if (isSearching) {
