    });

    if (uncheckedItems.length === 0) {
      alert(t('alerts.clipboard.noUncheckedItems'));
      return;
    }

    const textToCopy = uncheckedItems.join('\n');

    navigator.clipboard.writeText(textToCopy).then(() => {
      alert(t('alerts.clipboard.uncheckedSuccess'));
    }).catch(err => {
