  onAutoEditComplete?: () => void;
  advancedMode: boolean;
  enableSplitItemNames: boolean;
  lastInteractedInHomeViewId: string | null;
  onSetLastInteractedInHomeViewId: (id: string | null) => void;
}

const ShoppingList: React.FC<ShoppingListProps> = ({
  categories,
  allCurrentCategories,
  allShopCategories,
  allHomeCategories,
  itemMap,
  onUpdateItemAmount,
  onToggleItemCompleted,
  onDeleteItem,
  onCloneItem,
  onReorderItem,
  onMoveItemToCategory,
  onUpdateItem,
  onToggleDefaultCompleted,
  onToggleItemUrgent,
  onToggleItemUrgentOnce,
  onToggleHideUntilReset,
  onUpdateCategoryName,
  mode,
  hideCompleted,
  showOnlyUrgent,
  showOnlyDefaultCompleted,
  searchTerm,
  onAddCategoryAndMoveItem,
  itemToAutoEditId = null,
  onAutoEditComplete = () => {},
  advancedMode,
  enableSplitItemNames,
  lastInteractedInHomeViewId,
  onSetLastInteractedInHomeViewId,
}) => {
  const { t } = useLocalization();
  const [editingItemInfo, setEditingItemInfo] = useState<{ id: string; categoryId: string; } | null>(null);
  const [movingItemInfo, setMovingItemInfo] = useState<{ id: string; categoryId: string; viewMode: ViewMode } | null>(null);
  const scrollPositionRef = useRef(0);

  const visibleCategories = useMemo(() => {
    if (searchTerm.trim()) {
      return categories;
    }
    return getVisibleCategories(categories, itemMap, hideCompleted);
  }, [categories, itemMap, hideCompleted, searchTerm]);

  const { categoriesToRender, seldomNeededItems } = useMemo(() => {
    if (mode !== 'home') {
        return { categoriesToRender: visibleCategories, seldomNeededItems: [] };
    }

    const seldomItems: ShoppingListItemType[] = [];
    const processedCategories = visibleCategories.map(category => {
        const newItemIds = category.itemIds.filter(itemId => {
            const item = itemMap.get(itemId);
            if (item?.defaultCompleted) {
                seldomItems.push(item);
                return false;
            }
            return true;
        });
        return { ...category, itemIds: newItemIds };
    }).filter(category => category.itemIds.length > 0);

    const finalSeldomItems = hideCompleted
        ? seldomItems.filter(item => item.amount !== '0')
        : seldomItems;

    finalSeldomItems.sort((a, b) => a.name.localeCompare(b.name));

    return { categoriesToRender: processedCategories, seldomNeededItems: finalSeldomItems };
  }, [visibleCategories, itemMap, mode, hideCompleted]);

  const totalOriginalItemCount = useMemo(() => {
    return allCurrentCategories.reduce(
      (count, category) => count + category.itemIds.length,
      0
    );
  }, [allCurrentCategories]);

  const itemsInCurrentView = useMemo(() => {
    return categories.reduce(
      (count, category) => count + category.itemIds.length,
      0
    );
  }, [categories]);

  const {
    editingCategoryId,
    editedCategoryName,
    setEditedCategoryName,
    categoryInputRef,
    handleCategoryEditClick,
    handleCategorySave,
    handleCategoryKeyDown,
  } = useCategoryEditing(categories, onUpdateCategoryName, t);

  const {
    draggingItemId,
    dragOverCategoryId,
    handleDragStart,
    handleDrop,
    handleDragEnd,
    handleCategoryDrop,
    handleCategoryDragOver,
    handleCategoryDragLeave,
  } = useShoppingListDragAndDrop({ categories, itemMap, onReorderItem });

  const { handleMoveItemUp, handleMoveItemDown } = useShoppingListActions(
    categories,
    onReorderItem
  );

  const handleOpenEditModal = useCallback((itemId: string, categoryId: string) => {
    scrollPositionRef.current = window.scrollY;
    setEditingItemInfo({ id: itemId, categoryId });
  }, []);
  const handleCloseEditModal = useCallback(() => {
    setEditingItemInfo(null);
    setTimeout(() => {
      window.scrollTo(0, scrollPositionRef.current);
    }, 0);
  }, []);

  const handleOpenMoveModal = useCallback((itemId: string, categoryId: string) => {
    setMovingItemInfo({ id: itemId, categoryId, viewMode: mode });
  }, [mode]);
  const handleCloseMoveModal = useCallback(() => setMovingItemInfo(null), []);

  const handleMoveRequestFromEditModal = useCallback((viewMode: ViewMode) => {
    if (editingItemInfo) {
      setMovingItemInfo({ id: editingItemInfo.id, categoryId: editingItemInfo.categoryId, viewMode });
    }
  }, [editingItemInfo]);

  useEffect(() => {
    if (itemToAutoEditId && onAutoEditComplete) {
        const category = allCurrentCategories.find(s => s.itemIds.includes(itemToAutoEditId));
        if (category) {
            handleOpenEditModal(itemToAutoEditId, category.id);
        }
        onAutoEditComplete();
    }
  }, [itemToAutoEditId, onAutoEditComplete, allCurrentCategories, handleOpenEditModal]);

  const itemToEdit = useMemo(() => 
    editingItemInfo ? itemMap.get(editingItemInfo.id) : null,
    [editingItemInfo, itemMap]
  );

  const itemToMove = useMemo(() =>
    movingItemInfo ? itemMap.get(movingItemInfo.id) : null,
    [movingItemInfo, itemMap]
  );

  let finalLastInteractedInHomeViewId = lastInteractedInHomeViewId;
  let categoryForTopLine: string | null = null;

  if (mode === 'home' && lastInteractedInHomeViewId) {
      const lastCheckedItem = itemMap.get(lastInteractedInHomeViewId);
      if (lastCheckedItem && lastCheckedItem.amount === '0' && hideCompleted) {
          const allItemIdsWithCategories: {id: string, categoryId: string}[] = [];
          allCurrentCategories.forEach(s => s.itemIds.forEach(id => allItemIdsWithCategories.push({id, categoryId: s.id})));

          const hiddenItemIndex = allItemIdsWithCategories.findIndex(item => item.id === lastInteractedInHomeViewId);

          if(hiddenItemIndex > -1) {
              let predecessorId : string | null = null;
              for(let i = hiddenItemIndex - 1; i >= 0; i--) {
                  const potentialPredecessor = allItemIdsWithCategories[i];
                  if(itemMap.get(potentialPredecessor.id)?.amount !== '0') {
                      predecessorId = potentialPredecessor.id;
                      break;
                  }
              }

              if(predecessorId) {
                  finalLastInteractedInHomeViewId = predecessorId;
              } else {
                  finalLastInteractedInHomeViewId = null; 
                  if(visibleCategories.length > 0) {
                      categoryForTopLine = visibleCategories[0].id;
                  }
              }
          }
      }
  }

  const hasVisibleContent = categoriesToRender.length > 0 || (mode === 'home' && seldomNeededItems.length > 0);

  if (!hasVisibleContent) {
    if (searchTerm.trim()) {
        return (
            <div 
                id="search-no-results"
                className="text-center py-8 px-4 text-gray-500 dark:text-gray-400 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg"
            >
                <p className="text-xl font-medium">
                  {t('shoppingList.search.noResults')}
                </p>
            </div>
        );
    }
    if (totalOriginalItemCount === 0) {
        return <EmptyShoppingList mode={mode} />;
    }
    if ((showOnlyUrgent || showOnlyDefaultCompleted) && itemsInCurrentView === 0) {
        const filterMessages: string[] = [];
        if (showOnlyUrgent) filterMessages.push(`'${t('shoppingList.filterNames.urgent')}'`);
        if (showOnlyDefaultCompleted) filterMessages.push(`'${t('shoppingList.filterNames.checkedOnReset')}'`);

        const message = t('shoppingList.empty.filtered', filterMessages.join(' and '));

        return (
            <div 
                id="shopping-list-panel"
                role="tabpanel"
                aria-labelledby={`mode-tab-${mode}`}
                className="text-center py-8 px-4 text-gray-500 dark:text-gray-400 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg"
            >
                <p className="text-xl font-medium">{message}</p>
                <p className="mt-2">{t('shoppingList.empty.markInEdit')}</p>
            </div>
        );
    }
    if (hideCompleted) {
        const filterMessages: string[] = [];
        if (showOnlyUrgent) filterMessages.push(t('shoppingList.filterNames.urgent'));
        if (showOnlyDefaultCompleted) filterMessages.push(`"${t('shoppingList.filterNames.checkedOnReset')}"`);

        const message = filterMessages.length > 0
            ? t('shoppingList.empty.allFilteredCompleted', filterMessages.join(' and '))
            : t('shoppingList.empty.allCompleted');

        return (
            <div 
                id="shopping-list-panel"
                role="tabpanel"
                aria-labelledby={`mode-tab-${mode}`}
                className="text-center py-8 px-4 text-gray-500 dark:text-gray-400 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg"
            >
                <p className="text-xl font-medium">{message}</p>
                <p className="mt-2">
                  {t('shoppingList.empty.showCheckedPrompt')}
                </p>
            </div>
        );
    }
  }

  return (
    <>
      <div 
        className={AppConfig.interCategoryVerticalSpacingClass}
        id="shopping-list-panel"
        role="tabpanel"
        aria-labelledby={`mode-tab-${mode}`}
      >
        {categoriesToRender.map((category) => (
          <ShoppingListCategory
            key={category.id}
            category={category}
            itemMap={itemMap}
            editingCategoryId={editingCategoryId}
            editedCategoryName={editedCategoryName}
            categoryInputRef={categoryInputRef}
            dragOverCategoryId={dragOverCategoryId}
            draggingItemId={draggingItemId}
            onUpdateItemAmount={onUpdateItemAmount}
            onToggleItemCompleted={onToggleItemCompleted}
            onOpenEditModal={handleOpenEditModal}
            onOpenMoveModal={handleOpenMoveModal}
            onDragStart={handleDragStart}
            onDrop={handleDrop}
            onDragEnd={handleDragEnd}
            onMoveUp={handleMoveItemUp}
            onMoveDown={handleMoveItemDown}
            handleCategoryDrop={handleCategoryDrop}
            handleCategoryDragOver={handleCategoryDragOver}
            handleCategoryDragLeave={handleCategoryDragLeave}
            handleCategoryEditClick={handleCategoryEditClick}
            setEditedCategoryName={setEditedCategoryName}
            handleCategorySave={handleCategorySave}
            handleCategoryKeyDown={handleCategoryKeyDown}
            hideCompleted={hideCompleted}
            mode={mode}
            lastInteractedInHomeViewId={finalLastInteractedInHomeViewId}
            onSelectItem={onSetLastInteractedInHomeViewId}
            drawLineAtTop={category.id === categoryForTopLine}
          />
        ))}
      </div>
      {mode === 'home' && seldomNeededItems.length > 0 && (
          <section id="seldom-needed-section" className="mt-4">
              <div className={`border-b border-gray-200 dark:border-gray-700 pb-1 mb-2 sticky top-16 bg-white/80 dark:bg-black/80 backdrop-blur-sm z-20 ${AppConfig.categoryHeaderVerticalPaddingClass}`}>
                <div className="relative flex justify-center items-center group">
                    <h2 className={`w-full text-lg font-semibold ${AppConfig.categoryHeaderStyleClass}`}>
                        {t('shoppingList.filterNames.checkedOnReset')}
                    </h2>
                </div>
              </div>
              <ul className={`${AppConfig.listItemVerticalSpacingClass} pb-2`}>
                  {seldomNeededItems.map((item) => {
                      const originalCategory = allCurrentCategories.find(c => c.itemIds.includes(item.id));
                      const isUncategorized = originalCategory?.name.toLowerCase() === 'uncategorized';
                      const fallbackCategoryId = allCurrentCategories.find(c => c.name.toLowerCase() === 'uncategorized')?.id ?? allCurrentCategories[0]?.id;
                      const currentCategoryId = originalCategory?.id ?? fallbackCategoryId;

                      if (!currentCategoryId) {
                        return null;
                      }

                      return (
                          <ShoppingListItemComponent
                              key={item.id}
                              item={item}
                              index={0} // Not used as reordering is disabled
                              onUpdateAmount={onUpdateItemAmount}
                              onToggleItemCompleted={onToggleItemCompleted}
                              onOpenEditModal={(id) => handleOpenEditModal(id, currentCategoryId)}
                              onOpenMoveModal={(id) => handleOpenMoveModal(id, currentCategoryId)}
                              currentCategoryId={currentCategoryId}
                              onDragStart={(e) => e.preventDefault()}
                              onDrop={(e) => e.preventDefault()}
                              onDragEnd={(e) => e.preventDefault()}
                              isDragging={false}
                              onMoveUp={() => {}}
                              onMoveDown={() => {}}
                              isFirst={true} // Disables up arrow
                              isLast={true} // Disables down arrow
                              mode={mode}
                              isUncategorized={isUncategorized}
                              onSelectItem={onSetLastInteractedInHomeViewId}
                              showMoveControls={item.id === finalLastInteractedInHomeViewId}
                          />
                      );
                  })}
              </ul>
          </section>
      )}
      {itemToEdit && editingItemInfo && (
        <ItemEditModal
          item={itemToEdit}
          onClose={handleCloseEditModal}
          onUpdateItem={onUpdateItem}
          onDeleteItem={onDeleteItem}
          onCloneItem={onCloneItem}
          onToggleDefaultCompleted={onToggleDefaultCompleted}
          onToggleItemUrgent={onToggleItemUrgent}
          onToggleItemUrgentOnce={onToggleItemUrgentOnce}
          onToggleHideUntilReset={onToggleHideUntilReset}
          onMoveRequest={handleMoveRequestFromEditModal}
          advancedMode={advancedMode}
          enableSplitItemNames={enableSplitItemNames}
          isChildModalOpen={!!movingItemInfo}
        />
      )}
      {itemToMove && movingItemInfo && (
        <MoveItemModal
          item={itemToMove}
          categories={movingItemInfo.viewMode === 'shop' ? allShopCategories : allHomeCategories}
          currentCategoryId={movingItemInfo.categoryId}
          onMove={(newCategoryId) => {
            onMoveItemToCategory(movingItemInfo.id, newCategoryId, movingItemInfo.viewMode);
            handleCloseMoveModal();
          }}
          onClose={handleCloseMoveModal}
          onAddNewCategory={(newCategoryName) => {
            onAddCategoryAndMoveItem(newCategoryName, movingItemInfo.id, movingItemInfo.viewMode);
            handleCloseMoveModal();
          }}
          viewMode={movingItemInfo.viewMode}
        />
      )}
    </>
  );
};

export default ShoppingList;

const FILE_PATH = 'common/services/searchService.ts';
import type { Category, ShoppingListItem } from '../../types';
import { REMOVE_FROM_VIEW_CATEGORY_NAME } from '../../00configs/app.ts';

/**
 * Filters categories and their items based on a search term.
 *
 * @param categories The categories to filter.
 * @param itemMap A map of all shopping list items.
 * @param searchTerm The text to search for within item names.
 * @returns An array of categories containing only the items that match the search term.
 *          Categories without any matching items are excluded.
 */
export const filterVisibleCategories = (
    categories: Category[],
    itemMap: Map<string, ShoppingListItem>,
    searchTerm: string
): Category[] => {
    const trimmedSearchTerm = searchTerm.trim();
    const lowerCaseDeleteName = REMOVE_FROM_VIEW_CATEGORY_NAME.toLowerCase();

    if (!trimmedSearchTerm) {
        // No search term: filter out the "Remove from this view" category.
        const initiallyVisible = categories.filter(s => s.name.toLowerCase() !== lowerCaseDeleteName);
        // Return a deep copy to avoid potential mutation issues downstream
        return initiallyVisible.map(s => ({ ...s, itemIds: [...s.itemIds] }));
    }

    // With search term: search across all categories, including "Remove from this view".
    const lowerCaseSearchTerm = trimmedSearchTerm.toLowerCase();

    return categories.map(category => {
        const filteredItemIds = category.itemIds.filter(itemId => {
            const item = itemMap.get(itemId);
            if (!item) return false;

            const matchName = item.name.toLowerCase().includes(lowerCaseSearchTerm);
            const matchAlias = item.alias?.toLowerCase().includes(lowerCaseSearchTerm);

            return matchName || matchAlias;
        });

        return {
            ...category,
            itemIds: filteredItemIds
        };
    }).filter(category => category.itemIds.length > 0);
};

const FILE_PATH = 'components/ItemEditModal.tsx';
import React, { useState, useEffect, useRef } from 'react';
import { createPortal } from 'react-dom';
import type { ShoppingListItem, ViewMode } from '../types.ts';
import { IconTrash, IconCheck, IconFolder, IconArrowsPointingOut, IconArrowsPointingIn, IconDuplicate } from '../common/components/icons/index.ts';
import { useBodyScrollLock } from '../common/hooks/effects/useBodyScrollLock.ts';
import { usePrevious } from '../common/hooks/effects/usePrevious.ts';
import { useLongPressTooltip } from '../common/longPressTooltip/LongPressProvider.tsx';
import ConfirmModal from './ConfirmModal.tsx';
import { useLocalization } from '../localization/i18n.ts';
import AmountControl from './AmountControl.tsx';

interface ItemEditModalProps {
  item: ShoppingListItem;
  onClose: () => void;
  onUpdateItem: (id: string, updates: Partial<Pick<ShoppingListItem, 'name' | 'amount' | 'nameShop' | 'alias'>>) => void;
  onDeleteItem: (id: string) => void;
  onCloneItem: (id: string) => void;
  onToggleDefaultCompleted: (id: string) => void;
  onToggleItemUrgent: (id: string) => void;
  onToggleItemUrgentOnce: (id: string) => void;
  onToggleHideUntilReset: (id: string) => void;
  onMoveRequest: (mode: ViewMode) => void;
  advancedMode: boolean;
  enableSplitItemNames: boolean;
  isChildModalOpen?: boolean;
}

const ItemEditModal: React.FC<ItemEditModalProps> = ({ 
    item,
    onClose,
    onUpdateItem,
    onDeleteItem,
    onCloneItem,
    onToggleDefaultCompleted,
    onToggleItemUrgent,
    onToggleItemUrgentOnce,
    onToggleHideUntilReset,
    onMoveRequest,
    advancedMode,
    enableSplitItemNames,
    isChildModalOpen = false,
 }) => {
  useBodyScrollLock(!isChildModalOpen);
  const { t } = useLocalization();

  useEffect(() => {
    const handleResize = () => {
      window.scrollTo(0, 0);
    };

    const preventTouchMove = (e: globalThis.TouchEvent) => {
      if (e.target instanceof HTMLElement && e.target.closest('textarea')) {
          return;
      }
      e.preventDefault();
    };

    if (window.visualViewport) {
      window.visualViewport.addEventListener("resize", handleResize);
    }
    if (!isChildModalOpen) {
        document.body.addEventListener("touchmove", preventTouchMove, { passive: false });
    }

    return () => {
      if (window.visualViewport) {
        window.visualViewport.removeEventListener("resize", handleResize);
      }
      document.body.removeEventListener("touchmove", preventTouchMove);
    };
  }, [isChildModalOpen]);

  const [name, setName] = useState(item.name);
  const [nameShop, setNameShop] = useState(item.nameShop || '');
  const [alias, setAlias] = useState(item.alias || '');
  const [amount, setAmount] = useState(item.amount || '');
  const [isRushOnce, setIsRushOnce] = useState(!!item.isRushOnce);
  const [hideUntilReset, setHideUntilReset] = useState(!!item.hideUntilReset);
  const [isNameFullscreen, setIsNameFullscreen] = useState(false);
  const [isConfirmDeleteOpen, setIsConfirmDeleteOpen] = useState(false);
  const nameInputRef = useRef<HTMLTextAreaElement>(null);
  const fullscreenNameInputRef = useRef<HTMLTextAreaElement>(null);
  const prevItem = usePrevious(item);
  const prevIsNameFullscreen = usePrevious(isNameFullscreen);
  const longPressHandlers = useLongPressTooltip();

  // Effect for managing fullscreen state focus
  useEffect(() => {
    if (isNameFullscreen) {
      fullscreenNameInputRef.current?.focus();
    } else if (prevIsNameFullscreen) { // This means we are coming FROM fullscreen
      nameInputRef.current?.focus();
    }
  }, [isNameFullscreen, prevIsNameFullscreen]);

  // Effect for managing item change and initial focus
  useEffect(() => {
    const hasJustOpened = !prevItem || prevItem.id !== item.id;

    if (hasJustOpened) {
        setName(item.name);
        setNameShop(item.nameShop || '');
        setAlias(item.alias || '');
        setAmount(item.amount || '');
        setIsRushOnce(!!item.isRushOnce);
        setHideUntilReset(!!item.hideUntilReset);
        nameInputRef.current?.focus();
        nameInputRef.current?.select();
    }
  }, [item, prevItem]);

  const handleSave = () => {
    const newName = name.trim();
    const newNameShop = nameShop.trim();
    const newAlias = alias.trim();
    const newAmount = amount.trim();

    if (newName) { // An item must have a name to be valid
        const nameChanged = newName !== item.name;
        const nameShopChanged = newNameShop !== (item.nameShop || '');
        const aliasChanged = newAlias !== (item.alias || '');
        const amountChanged = newAmount !== (item.amount || '');
        if (nameChanged || amountChanged || nameShopChanged || aliasChanged) {
            onUpdateItem(item.id, { name: newName, amount: newAmount, nameShop: newNameShop, alias: newAlias });
        }
    }

    if (isRushOnce !== !!item.isRushOnce) {
        onToggleItemUrgentOnce(item.id);
    }
    if (hideUntilReset !== !!item.hideUntilReset) {
        onToggleHideUntilReset(item.id);
    }

    onClose();
  };

  const handleDelete = () => {
    setIsConfirmDeleteOpen(true);
  };

  const handleConfirmDelete = () => {
    onDeleteItem(item.id);
    onClose();
  };

  const handleClone = () => {
    onCloneItem(item.id);
    onClose();
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
        e.preventDefault();
        handleSave();
    } else if (e.key === 'Escape') {
      handleSave();
    }
  };

  const displayName = [item.amount, item.name].filter(Boolean).join(' ').trim();

  const handleAmountUpdate = (delta: number) => {
    let currentValue: number;
    const parsedAmount = parseInt(amount || 'not a number', 10);

    if (!isNaN(parsedAmount)) {
        currentValue = parsedAmount;
    } else {
        currentValue = item.amount === '0' ? 0 : 1;
    }

    const newValue = currentValue + delta;
    setAmount(String(newValue));
  };

  return createPortal(
    <>
      <div
        className="fixed inset-0 z-50"
        role="dialog"
        aria-modal="true"
        aria-labelledby="edit-item-title"
      >
        <div
          className="bg-white dark:bg-gray-900 w-full h-full flex flex-col overflow-hidden pb-[env(keyboard-inset-bottom,0px)]"
          onClick={(e) => e.stopPropagation()}
        >
          <header className="flex items-center justify-between p-3 border-b border-gray-200 dark:border-gray-700">
            <h2 id="edit-item-title" className="text-lg font-bold dark:text-white">{t('itemEditModal.title')}</h2>
            <button
              onClick={handleSave}
              className="flex items-center justify-center px-3 py-1.5 text-sm bg-green-600 text-white rounded-md hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-white dark:focus:ring-offset-gray-900 focus:ring-green-500 transition"
              title={t('itemEditModal.tooltips.save')}
              {...longPressHandlers}
            >
              <IconCheck className="h-5 w-5 mr-2" />
              {t('itemEditModal.save')}
            </button>
          </header>

          <main className="p-4 space-y-4 flex-1 flex flex-col">
            <div>
              <label htmlFor="item-name-input" className="block text-sm font-medium text-gray-700 dark:text-white mb-1">{t(enableSplitItemNames ? 'itemEditModal.itemNameHomeLabel' : 'itemEditModal.itemNameLabel')}</label>
              <div className="relative">
                <textarea
                    id="item-name-input"
                    ref={nameInputRef}
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    onKeyDown={handleKeyDown}
                    rows={2}
                    className="w-full p-2 pr-10 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md focus:ring-2 focus:ring-orange-500 focus:outline-none transition dark:text-white resize-none"
                    title={t('itemEditModal.tooltips.itemName')}
                    {...longPressHandlers}
                />
                <button
                    type="button"
                    onClick={() => setIsNameFullscreen(true)}
                    className="absolute top-2 right-2 p-1 text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 rounded-full hover:bg-gray-200 dark:hover:bg-gray-600"
                    aria-label={t('itemEditModal.aria.fullscreen')}
                    title={t('itemEditModal.tooltips.fullscreen')}
                    {...longPressHandlers}
                >
                    <IconArrowsPointingOut className="h-5 w-5" />
                </button>
              </div>
            </div>
            {enableSplitItemNames && (
                <div>
                    <label htmlFor="item-name-shop-input" className="block text-sm font-medium text-gray-700 dark:text-white mb-1">{t('itemEditModal.itemNameShopLabel')}</label>
                    <textarea
                        id="item-name-shop-input"
                        value={nameShop}
                        onChange={(e) => setNameShop(e.target.value)}
                        onKeyDown={handleKeyDown}
                        rows={2}
                        className="w-full p-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md focus:ring-2 focus:ring-orange-500 focus:outline-none transition dark:text-white resize-none"
                        placeholder={name}
                        title={t('itemEditModal.tooltips.itemNameShop')}
                        {...longPressHandlers}
                    />
                </div>
            )}
            <div>
                <label htmlFor="item-alias-input" className="block text-sm font-medium text-gray-700 dark:text-white mb-1">{t('itemEditModal.aliasLabel')}</label>
                <textarea
                    id="item-alias-input"
                    value={alias}
                    onChange={(e) => setAlias(e.target.value)}
                    onKeyDown={handleKeyDown}
                    rows={1}
                    className="w-full p-2 bg-gray-50 dark:bg-gray-700 border border-gray-300 dark:border-gray-600 rounded-md focus:ring-2 focus:ring-orange-500 focus:outline-none transition dark:text-white resize-none"
                    title={t('itemEditModal.tooltips.alias')}
                    {...longPressHandlers}
                />
            </div>
            <div>
                <label htmlFor="item-amount-input" className="block text-sm font-medium text-gray-700 dark:text-white mb-1">{t('itemEditModal.amountLabel')}</label>
                <div className="flex gap-2 items-center">
                    <div className="w-1/3 flex justify-center">
                        <AmountControl
                            id="item-amount-input"
                            amountToDisplay={amount || (item.amount === '0' ? '0' : '1')}
                            onIncrease={() => handleAmountUpdate(1)}
                            onDecrease={() => handleAmountUpdate(-1)}
                            displayName={name}
                        />
                    </div>
                    {!item.defaultCompleted && (
                        <button
                            id="select-home-category-button"
                            type="button"
                            onClick={() => onMoveRequest('home')}
                            className="w-1/3 flex items-center justify-center px-3 py-2 text-sm text-white bg-blue-600 hover:bg-blue-700 rounded-md transition focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-white dark:focus:ring-offset-gray-900 focus:ring-blue-500 text-center"
                            title={t('itemEditModal.tooltips.selectHomeCategory')}
                            {...longPressHandlers}
                        >
                            <IconFolder className="h-5 w-5 mr-2 flex-shrink-0" />
                            <span className="break-words">{t('itemEditModal.selectHomeCategory')}</span>
                        </button>
                    )}
                    <button
                        id="select-shop-category-button"
                        type="button"
                        onClick={() => onMoveRequest('shop')}
                        className={`${item.defaultCompleted ? 'w-2/3' : 'w-1/3'} flex items-center justify-center px-3 py-2 text-sm text-white bg-blue-600 hover:bg-blue-700 rounded-md transition focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-white dark:focus:ring-offset-gray-900 focus:ring-blue-500 text-center`}
                        title={t('itemEditModal.tooltips.selectShopCategory')}
                        {...longPressHandlers}
                    >
                        <IconFolder className="h-5 w-5 mr-2 flex-shrink-0" />
                        <span className="break-words">{t('itemEditModal.selectShopCategory')}</span>
                    </button>
                </div>
            </div>
            <div className="flex items-center mt-auto border-t border-gray-200 dark:border-gray-700 pt-4">
              <div className={`flex flex-col space-y-1 ${advancedMode ? 'w-1/3' : 'flex-grow'}`}>
                  <div className="flex items-center">
                      <input
                        id={`reset-behavior-once-${item.id}`}
                        name={`reset-behavior-${item.id}`}
                        type="radio"
                        checked={!!item.defaultCompleted}
                        onChange={() => {
                            if (!item.defaultCompleted) onToggleDefaultCompleted(item.id);
                        }}
                        className="h-4 w-4 border-gray-300 dark:border-gray-600 text-orange-600 focus:ring-orange-500 cursor-pointer"
                        title={t('itemEditModal.tooltips.seldomNeeded')}
                        {...longPressHandlers}
                      />
                      <label 
                        htmlFor={`reset-behavior-once-${item.id}`}
                        className="ml-2 select-none text-sm text-gray-700 dark:text-white cursor-pointer"
                        title={t('itemEditModal.tooltips.seldomNeeded')}
                        {...longPressHandlers}
                      >
                        <b>{t('itemEditModal.seldomNeeded')}</b>
                      </label>
                  </div>
                  <div className="flex items-center">
                      <input
                        id={`reset-behavior-always-${item.id}`}
                        name={`reset-behavior-${item.id}`}
                        type="radio"
                        checked={!item.defaultCompleted}
                        onChange={() => {
                            if (item.defaultCompleted) onToggleDefaultCompleted(item.id);
                        }}
                        className="h-4 w-4 border-gray-300 dark:border-gray-600 text-orange-600 focus:ring-orange-500 cursor-pointer"
                        title={t('itemEditModal.tooltips.oftenNeeded')}
                        {...longPressHandlers}
                      />
                      <label 
                        htmlFor={`reset-behavior-always-${item.id}`}
                        className="ml-2 select-none text-sm text-gray-700 dark:text-white cursor-pointer"
                        title={t('itemEditModal.tooltips.oftenNeeded')}
                        {...longPressHandlers}
                      >
                        <b>{t('itemEditModal.oftenNeeded')}</b>
                      </label>
                  </div>

                  <button
                    id="clone-item-button"
                    type="button"
                    onClick={handleClone}
                    className="flex items-center justify-center mt-3 px-3 py-1.5 text-sm bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 dark:hover:bg-gray-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-white dark:focus:ring-offset-gray-900 focus:ring-gray-500 transition"
                    title={t('itemEditModal.tooltips.clone')}
                    {...longPressHandlers}
                  >
                    <IconDuplicate className="h-4 w-4 mr-2" />
                    {t('itemEditModal.clone')}
                  </button>
              </div>

              {advancedMode && (
                  <div className="w-1/3 flex flex-col items-start justify-center pl-4 space-y-2">
                      <div className="flex items-center">
                          <input
                            id="is-urgent-checkbox"
                            data-testid="item-edit-urgent-checkbox"
                            type="checkbox"
                            checked={!!item.isRush}
                            onChange={() => onToggleItemUrgent(item.id)}
                            className="h-4 w-4 rounded border-gray-300 dark:border-gray-600 text-orange-600 focus:ring-orange-500 cursor-pointer"
                            {...longPressHandlers}
                            title={t('itemEditModal.tooltips.urgentAlways')}
                          />
                          <label
                            htmlFor="is-urgent-checkbox"
                            className="ml-2 select-none text-sm text-gray-700 dark:text-white cursor-pointer"
                            title={t('itemEditModal.tooltips.urgentAlways')}
                            {...longPressHandlers}
                          >
                              <strong>{t('itemEditModal.urgentAlways')}</strong>
                          </label>
                      </div>
                      <div className="flex items-center">
                          <input
                              id="is-urgent-once-checkbox"
                              data-testid="item-edit-urgent-once-checkbox"
                              type="checkbox"
                              checked={isRushOnce}
                              onChange={(e) => setIsRushOnce(e.target.checked)}
                              className="h-4 w-4 rounded border-gray-300 dark:border-gray-600 text-orange-600 focus:ring-orange-500 cursor-pointer"
                              {...longPressHandlers}
                              title={t('itemEditModal.tooltips.urgentThisTime')}
                          />
                          <label
                              htmlFor="is-urgent-once-checkbox"
                              className="ml-2 select-none text-sm text-gray-700 dark:text-white cursor-pointer"
                              title={t('itemEditModal.tooltips.urgentThisTime')}
                              {...longPressHandlers}
                          >
                              <strong>{t('itemEditModal.urgentThisTime')}</strong>
                          </label>
                      </div>
                  </div>
              )}

              <div className={`flex flex-col items-end ${advancedMode ? 'w-1/3' : 'flex-shrink-0'}`}>
                {advancedMode && (
                    <div className="flex items-center mb-2">
                        <input
                            id="hide-until-reset-checkbox"
                            type="checkbox"
                            checked={hideUntilReset}
                            onChange={(e) => setHideUntilReset(e.target.checked)}
                            className="h-4 w-4 rounded border-gray-300 dark:border-gray-600 text-orange-600 focus:ring-orange-500 cursor-pointer"
                            {...longPressHandlers}
                            title={t('itemEditModal.tooltips.hideUntilReset')}
                        />
                        <label
                            htmlFor="hide-until-reset-checkbox"
                            className="ml-2 select-none text-sm text-gray-700 dark:text-white cursor-pointer"
                            title={t('itemEditModal.tooltips.hideUntilReset')}
                            {...longPressHandlers}
                        >
                            <strong>{t('itemEditModal.hideUntilReset')}</strong>
                        </label>
                    </div>
                )}
                <button
                  id="delete-item-button"
                  onClick={handleDelete}
                  className="flex items-center justify-center px-3 py-1.5 text-sm bg-red-600 text-white rounded-md hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-white dark:focus:ring-offset-gray-900 focus:ring-red-500 transition"
                  title={t('itemEditModal.tooltips.delete')}
                  {...longPressHandlers}
                >
                  <IconTrash className="h-5 w-5 mr-2" />
                  {t('itemEditModal.delete')}
                </button>
              </div>
            </div>
          </main>
        </div>
      </div>
      {isNameFullscreen && (
        <div className="fixed inset-0 bg-black/90 backdrop-blur-sm z-[60] flex flex-col p-4"
             role="dialog"
             aria-modal="true"
             aria-labelledby="fullscreen-edit-title">
          <header className="flex items-center justify-between mb-4 flex-shrink-0">
            <h2 id="fullscreen-edit-title" className="text-lg font-bold text-white">{t('itemEditModal.itemNameLabel')}</h2>
            <button 
                onClick={() => setIsNameFullscreen(false)} 
                className="p-2 rounded-full text-white hover:bg-white/20"
                aria-label={t('itemEditModal.aria.exitFullscreen')}
                title={t('itemEditModal.tooltips.exitFullscreen')}
                {...longPressHandlers}
            >
                <IconArrowsPointingIn className="h-6 w-6" />
            </button>
          </header>
          <div className="flex-1 flex">
            <textarea
                ref={fullscreenNameInputRef}
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="w-full h-full bg-transparent text-white text-xl p-2 focus:outline-none resize-none"
            />
          </div>
        </div>
      )}
      <ConfirmModal
        isOpen={isConfirmDeleteOpen}
        onClose={() => setIsConfirmDeleteOpen(false)}
        onConfirm={handleConfirmDelete}
        title={t('itemEditModal.confirmDelete.title')}
        confirmText={t('itemEditModal.delete')}
      >
        <p>{t('itemEditModal.confirmDelete.message', displayName)}</p>
      </ConfirmModal>
    </>,
    document.body
  );
};

